from typing import Protocol, runtime_checkable

@runtime_checkable
class Closeable(Protocol):
    def close(self) -> None: ...

class Conn:
    def close(self) -> None:
        print("conn closed")

things = [Conn(), open, "text", Conn]
for t in things:
    print(type(t).__name__, isinstance(t, Closeable))

Conn().close()
print(issubclass(Conn, Closeable))
